 {
    data.Read(MemoryClass::HOST, size);
    const int n = dofs.Size();
    for (int i = 0; i < n; i++)
    {
       const int j = dofs[i];
       elem_data[i] = (j >= 0) ? data[j] : -data[-1-j];
    }
