 {
    int j, k;

    for (k = 0; k < spaceDim; k++)
    {
       vertices[result](k) = vertices[indexes[0]](k);
    }

    for (j = 1; j < n; j++)
       for (k = 0; k < spaceDim; k++)
       {
          vertices[result](k) += vertices[indexes[j]](k);
       }

    for (k = 0; k < spaceDim; k++)
    {
       vertices[result](k) *= (1.0 / n);

