                             &BilinearForm::AddBdrFaceIntegrator, ir_face);

    a->Assemble();
    a->FormSystemMatrix(ess_dofs, A);

    ResetIntegrationRules(&BilinearForm::GetDBFI);
    ResetIntegrationRules(&BilinearForm::GetFBFI);
    ResetIntegrationRules(&BilinearForm::GetBBFI);
