  * computes:
  * a1 = max(a1, b1)
  * a0 = (a1 == 0 ? 0 : sum_{k in union(i,j)} (|v_k|/a1)^p)
  *
  * This form is resiliant against overflow/underflow, similar to std::hypot
  */
 struct LpReducer
