    real_t p;
    using value_type = DevicePair<real_t, real_t>;
-   MFEM_HOST_DEVICE void join(value_type& a, const value_type &b) const
+   MFEM_HOST_DEVICE void Join(value_type& a, const value_type &b) const
    {
