 int KnotVector::findKnotSpan(double u) const
 {
    int low, mid, high;

    if (u == knot(NumOfControlPoints+Order))
    {
       mid = NumOfControlPoints;
    }
    else
    {
       low = Order;
       high = NumOfControlPoints + 1;
       mid = (low + high)/2;
       while ( (u < knot(mid-1)) || (u > knot(mid)) )
       {
          if (u < knot(mid-1))
          {
             high = mid;
          }
          else
          {
             low = mid;
          }

